/* Each original gzip-compressed resource is now a small external file. */
async function embeddedAsset(path){
  const response=await fetch(new URL(path+'.gz', document.baseURI));
  if(!response.ok)return response;
  if(typeof DecompressionStream==='undefined')throw Error('Gzip streaming is unsupported in this browser');
  return new Response(response.body.pipeThrough(new DecompressionStream('gzip')));
}
